// Keep the downloaded portfolio usable when opened directly from Finder.
const portfolioLocal = location.protocol === 'file:';
const portfolioRoot = new URL('.', document.currentScript.src);
function portfolioURL(value) {
 if (!portfolioLocal || !value.startsWith('/') || value.startsWith('//')) return value;
 const url = new URL(value.slice(1), portfolioRoot);
 if (url.pathname.endsWith('/')) url.pathname += 'index.html';
 return url.href;
}
function portfolioMarkup(html) {
 if (!portfolioLocal) return html;
 return html.replace(/((?:href|src|data-zoom-src|data-comparison-image)=["'])(\/(?!\/)[^"']*)(["'])/g,
  (_,prefix,value,quote)=>prefix+portfolioURL(value)+quote);
}
const companies=[
 {id:'healthsherpa',name:'HealthSherpa',desc:'Tools that help health insurance agents navigate and manage ACA enrollments with confidence',sector:'Health Marketplace CRM',projects:[['A new homepage for health marketplace agents','Agent homepage','Product design · UX research · Interaction design'],['Streamline client renewals for the 2026 enrollment year','Client renewals','Product design • UX research']]},
 {id:'calendly',name:'Calendly',desc:'Streamlining the scheduling process with personalized tools for businesses to manage meetings',sector:'Scheduling',projects:[['Driving adoption of admin scheduling templates','Managed-event adoption','Growth • Product design • Usability testing • Experimentation • Visual design'],['Improving activation for new Calendly users','New-user onboarding','Growth • Usability testing • Experimentation'],['Pricing, paywalls, and personalized plans','Monetization','Growth • Product design • UX research • Experimentation']]},
 {id:'ukg',name:'UKG',desc:'Simplifying performance development to make employee growth more actionable',sector:'HR technology',projects:[['Making employee feedback actionable on mobile','Continuous feedback','Product design • UX research • Hybrid mobile app']]},
 {id:'side-quests',name:'Side quests',desc:'A messy visual collection of explorations or side projects with small teams',sector:'Independent work',projects:[]}
];
const all=companies.flatMap(c=>c.projects.map((project,pi)=>({company:c,pi,title:project[0],type:project[1],skills:project[2],href:`/work/${c.id}/${pi+1}/`,featured:!(c.id==='calendly'&&pi===2)&&c.id!=='ukg'&&!(c.id==='healthsherpa'&&pi===1),image:c.id==='calendly'&&pi===2?'/assets/calendly-mon-hero.svg?v=3':c.id==='ukg'?'/assets/ukg-mobile-hero.svg?v=4':c.id==='healthsherpa'?(pi===0?'/assets/healthsherpa-agent-home-final.png':'/assets/hs-renewals-18.png'):pi===0?'/assets/calendly-case-study-hero.png':'/assets/calendly-nu-01.png',impact:c.id==='calendly'&&pi===2?'+10% increase in paid conversion':c.id==='ukg'?'1,000+ active employees sharing feedback during Beta launch':c.id==='healthsherpa'?(pi===0?'80%+ agent base engagement during the Special Enrollment Period':'Contributed to 30%+ increase in 2026 enrollments'):pi===0?'+60% increase in adoption of admin features':'+5% increase in meetings booked'})));
const isWorkInProgress=p=>false;
const publishedProjects=all.filter(p=>!isWorkInProgress(p));
const app=document.getElementById('app');
const arrowIcon=(direction='right')=>`<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${direction==='left'?'M19 12H5m0 0 6.5 6.5M5 12l6.5-6.5':'M5 12h14m0 0-6.5-6.5M19 12l-6.5 6.5'}"/></svg>`;
const upIcon=()=>`<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 19V5m0 0-6.5 6.5M12 5l6.5 6.5"/></svg>`;
const sparkleIcon=()=>`<svg class="ui-icon sparkle-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11 2c0 5.5-3.5 9-9 9 5.5 0 9 3.5 9 9 0-5.5 3.5-9 9-9-5.5 0-9-3.5-9-9Z"/><path d="M19 18v4m-2-2h4M19 2v4m-2-2h4"/></svg>`;
function companyMark(c){return `<span class="company-mark ${c.id==='side-quests'?'side-quest-mark':`company-mark-${c.id}`}" aria-hidden="true"><img src="/assets/${c.id}-mark.svg${c.id==='side-quests'?'?v=star-20261017':''}" alt=""></span>`}
const cafeEmbed = new URLSearchParams(location.search).has('cafe');
if(cafeEmbed)document.documentElement.classList.add('cafe-embed');
function header(){if(cafeEmbed)return '';return `<div id="page-top" aria-hidden="true"></div><header class="site-header"><nav class="nav" aria-label="Primary"><a href="/">Home</a><a href="/#work">Work</a><a href="/#about">About</a><a class="resume-link" href="/assets/amber-tang-2026-resume.pdf?v=20261018-updated" aria-haspopup="dialog" aria-controls="resume-viewer">Resume</a></nav></header>`}
function footer(){if(cafeEmbed)return '';return `<footer class="footer"><div class="footer-inner wrap"><span>Designed and vibe coded by me 👾</span><div class="footer-links"><a href="#page-top">Back to top ${upIcon()}</a></div></div></footer>`}
function healthSherpaShowcase(){return `<div class="hs-showcase" aria-hidden="true"><div class="hs-desktop-shot"><img src="/assets/healthsherpa-agent-home-final.png" alt=""></div></div>`}
function calendlyShowcase(p){return `<div class="cal-showcase" aria-hidden="true"><div class="cal-screen"><img src="${p.image}" alt=""></div></div>`}
function projectCard(p,large=false,featured=false,origin='company'){const health=p.company.id==='healthsherpa';const activation=isWorkInProgress(p);const tag=activation?'div':'a';const attributes=activation?'aria-label="Improving activation for new Calendly users, work in progress"':`href="${p.href}?from=${origin}" aria-label="View case study: ${p.title}"`;return `<${tag} class="project-card split-card ${health?'healthsherpa-card':p.company.id==='ukg'?'ukg-card':'calendly-card'} ${p.company.id==='calendly'&&p.pi===1?'activation-card':''} ${p.company.id==='calendly'&&p.pi===2?'monetization-card':''} ${p.company.id==='healthsherpa'&&p.pi===1?'renewals-card':''} ${large?'large':''}" ${attributes}><span class="project-info"><span class="project-copy"><span class="overline">${p.company.name}</span><strong class="project-title">${p.title}</strong><span class="project-meta"><span class="project-impact">${p.impact}</span><span class="project-skills" aria-label="Skills demonstrated">${p.skills.split(/[•·,]/).map(skill=>skill.trim()).filter(Boolean).map(skill=>`<span class="project-skill">${skill}</span>`).join('')}</span></span></span>${activation?'<span class="work-in-progress-label"><em>Work in progress</em></span>':`<span class="view-project" aria-hidden="true">View project</span>`}</span><span class="project-media" aria-hidden="true"><img src="${p.image}" alt="" loading="${origin==='selected'?'eager':'lazy'}" decoding="async"></span></${tag}>`}

function experienceTimeline(){return `<div class="experience-timeline wrap" id="experience" aria-labelledby="experience-title"><div class="experience-heading"><h2 id="experience-title">Experience</h2><a class="button primary experience-resume" href="/assets/amber-tang-2026-resume.pdf?v=20261018-updated" aria-haspopup="dialog" aria-controls="resume-viewer">View PDF</a></div><ol class="experience-list"><li class="experience-row"><div class="experience-role"><h3>Senior Product Designer II</h3><span class="experience-company">HealthSherpa</span><div class="experience-date">Jan 2025 — Present</div></div><div class="experience-detail"><p>Designing core experiences for health insurance agents to better serve and enroll their clients through the federal and individual state marketplaces. Initiatives contributed to $4M enrollments, increased engagement with underutilized features by up to 300%, and improved new user activation rate of the referral program by 7%.</p></div></li><li class="experience-row"><div class="experience-role"><h3>Senior Product Designer (Growth)</h3><span class="experience-company">Calendly</span><div class="experience-date">Nov 2021 — Jan 2025</div></div><div class="experience-detail"><p>Led design experimentation for Calendly’s growth initiatives. Increased subscription purchases by 10% and adoption of features associated with high retention by up to 106%. Contributed to multimillion-dollar annual recurring revenue by owning design for checkout, paywalls, pricing, add-ons, volume pricing, and churn reporting.</p></div></li><li class="experience-row"><div class="experience-role"><h3>Senior UI &amp; UX Designer</h3><span class="experience-company">UKG</span><div class="experience-date">Sep 2020 — Oct 2021</div></div><div class="experience-detail"><p>Led design for an employee coaching product with NLP feedback analysis, awarded <a class="experience-award" href="https://hrexecutive.com/ukg-pro-coaching-and-development/" target="_blank" rel="noopener noreferrer">Top HR Product</a> for 2021. Designed a 0-to-1 Work Crafting app and helped shape the product strategy to unify 10+ legacy products into a talent management platform.</p></div></li><li class="experience-row"><div class="experience-role"><h3>User Experience Designer</h3><span class="experience-company">Ultimate Software</span><div class="experience-date">Jan 2018 — Aug 2020</div></div><div class="experience-detail"><p>Designed 0-to-1 HR talent development, performance review, and payroll products across iOS, Android, and web. Led research and design for a company engagement survey benchmark tool adopted by 500 companies.</p></div></li></ol></div>`}
function home(){let selected=publishedProjects.filter(p=>p.featured!==false);return `<main><section class="hero wrap hero-without-chat"><div class="hero-star-grid" aria-hidden="true"></div><h1>Amber <em>Tang</em></h1><p class="hero-intro">I’m a <strong>senior product designer</strong> with 8 years of experience shaping B2B products through strategy, growth, and design. I connect the dots between what businesses need, what people say, and what they actually do.</p><div class="hero-actions"><div class="hero-career"><span class="availability">Currently designing at HealthSherpa</span><span class="availability">Previously at Calendly and UKG</span></div><a class="button primary" href="#work">Explore my work</a></div></section><div class="work-chapter" id="work"><section class="selected section"><div class="wrap section-head"><div><h2>Selected work</h2></div></div><div class="carousel" id="carousel">${[...selected,...selected,...selected].map((p,i)=>projectCard(p,true,true,'selected').replace('class="project-card',`data-carousel-copy="${Math.floor(i/selected.length)}" class="project-card`)).join('')}</div><div class="carousel-controls wrap"><button id="prev" aria-label="Previous project">${arrowIcon('left')}</button><div class="carousel-track" role="scrollbar" tabindex="0" aria-label="Selected work position" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><div class="carousel-thumb" id="carousel-thumb"></div></div><button id="next" aria-label="Next project">${arrowIcon()}</button></div></section><section class="companies wrap section" id="more-projects"><div class="section-head bordered"><div><h2>More projects</h2></div></div><div class="company-grid">${companies.map((c,i)=>`<a class="company-card company-${i}" href="/work/${c.id}/"><div class="company-card-media">${companyMark(c)}</div><div class="company-card-content"><span class="company-sector">${c.sector}</span><h3>${c.name}</h3><p>${c.desc}</p></div><span class="company-card-arrow" aria-hidden="true">${arrowIcon()}</span></a>`).join('')}</div></section></div><section class="about section" id="about"><div class="wrap about-grid"><div class="about-copy"><h2>About me</h2><div class="about-body"><div class="about-prose"><p>I’m a product designer based in Los Angeles who cares deeply about craft but is equally pragmatic about how things get built. I partner closely with product and engineering to turn complex problems into meaningful outcomes.</p><p>My experience spans product and growth design, from generative research and product strategy to visual polish and QA. I’ve worked across teams of all sizes and industries, including enterprise B2B SaaS, HR tech, health insurance, and even small indie web games.</p><p>WWhen I’m not designing, I’m probably doing something active or walking the aisles of Costco.</p></div><div class="about-skills"><div class="skills-heading">Some skills</div><div class="skill-list"><span>Design workshops</span><span>Discovery research</span><span>Information architecture</span><span>Interaction design</span><span>Product design</span><span>Product strategy</span><span>Responsive design</span><span>Usability testing</span><span>UX audits</span><span>UX prompt engineering</span><span>Vibe coding</span></div></div></div></div><button class="about-art portrait-card" id="portrait-card" type="button" aria-label="Illustrated portrait of Amber. Hover or press to see a little reaction"><img class="portrait-frame portrait-base" src="/assets/amber-portrait-purple.png" alt="" draggable="false"><img class="portrait-frame portrait-blink" src="/assets/amber-portrait-blink.png" alt="" draggable="false"><span class="portrait-particle" aria-hidden="true"></span><span class="portrait-sparkle portrait-sparkle-one" aria-hidden="true">${sparkleIcon()}</span><span class="portrait-sparkle portrait-sparkle-two" aria-hidden="true">${sparkleIcon()}</span></button></div>${experienceTimeline()}</section></main>`}
