function sideQuestTile([n,size,label]){const src=typeof n==='number'?`/assets/side-quests/sq-${String(n).padStart(2,'0')}.png`:`/assets/side-quests/${n}`;return `<button class="sq-tile sq-${size}" type="button" data-zoom-src="${src}" data-zoom-name="${label}" aria-label="Enlarge ${label}"><img src="${src}" alt="${label}" loading="lazy"></button>`}
function sideQuestsPage(c){return `<main class="sq-page"><section class="detail-intro wrap"><a class="back-link back-all-work" href="/#more-projects">${arrowIcon('left')} All projects</a><h1>${c.name}</h1><p>${c.desc}</p></section><div class="sq-collection wrap">${sideQuestGroups.map(group=>`<section class="sq-group sq-group-${group.id}" aria-label="${group.label}">${group.portraits?`<div class="sq-portrait-grid">${group.portraits.map(n=>sideQuestTile([n,'portrait','Character study'])).join('')}</div>`:`<div class="sq-grid">${group.tiles.map(sideQuestTile).join('')}</div>`}</section>`).join('')}</div>${cafeEmbed?"":companyNavigation(c)}</main>`}

function companyPage(c){if(c.id==='side-quests')return sideQuestsPage(c);let ps=all.filter(p=>p.company.id===c.id);let next=companies.filter(company=>company.projects.length).find(company=>company.id!==c.id);return `<main><section class="detail-intro wrap"><a class="back-link back-all-work" href="/#work">${arrowIcon('left')} All projects</a><h1>${c.name}</h1><p>${c.desc}</p></section>${ps.length?`<section class="company-projects wrap">${ps.map(p=>projectCard(p,true,true,'company')).join('')}</section>${companyNavigation(c)}`:`<section class="company-empty wrap" aria-label="Projects coming soon"><div class="company-empty-mark">${companyMark(c)}</div><div class="company-empty-copy"><span class="eyebrow">MORE TO COME</span><h2>Case studies coming soon</h2><p>${c.id==='ukg'?'I’m preparing a closer look at my work on performance development and coaching.':'I’m gathering a few experiments and collaborations to share here.'} In the meantime, explore my published work.</p><a class="button primary" href="/#work">Explore selected work ${arrowIcon()}</a></div></section>`}</main>`}
function caseOrigin(p){return {href:`/work/${p.company.id}/`,label:`All ${p.company.name} projects`}}
function caseBreadcrumb(p){return ''}
function casePage(p){if(p.company.id==='calendly'&&p.pi===2)return monetizationCasePage(p);if(p.company.id==='ukg')return ukgMobileCasePage(p);if(p.company.id==='healthsherpa')return p.pi===1?renewalsCasePage(p):healthSherpaCasePage(p);return p.pi===0?calendlyCasePage(p):activationCasePage(p)}
function caseProgress(index,total,label){const current=String(index).padStart(2,'0'),count=String(total).padStart(2,'0');return `<div class="case-progress" aria-label="Section ${index} of ${total}: ${label}"><span class="eyebrow">${current} OF ${count} / ${label}</span><span class="case-progress-track" aria-hidden="true">${Array.from({length:total},(_,i)=>`<svg class="${i<index?'done':''}" viewBox="0 0 20 20" focusable="false"><path d="M10 1c0 5-3 9-9 9 6 0 9 4 9 9 0-5 3-9 9-9-6 0-9-4-9-9Z" fill="currentColor"/></svg>`).join('')}</span></div>`}
function companyNavigation(c){const index=companies.findIndex(item=>item.id===c.id),previous=companies[(index-1+companies.length)%companies.length],next=companies[(index+1)%companies.length];return `<nav class="next-work wrap inventory-navigation" aria-label="Company projects"><a class="inventory-previous" href="/work/${previous.id}/">${arrowIcon('left')}<span>${previous.name}</span></a><a class="inventory-next" href="/work/${next.id}/"><span>${next.name}</span>${arrowIcon()}</a></nav>`}
function caseNextWork(p){const current=publishedProjects.findIndex(item=>item.company.id===p.company.id&&item.pi===p.pi),next=publishedProjects[(current+1)%publishedProjects.length];return `<div class="case-footer-band"><nav class="next-work wrap case-next-work case-footer-actions" aria-label="Case study navigation"><a class="back-link back-all-work" href="/work/${p.company.id}/">${arrowIcon('left')} All ${p.company.name} projects</a><a class="next-project-link" href="${next.href}"><strong>Up Next ${arrowIcon()}</strong><small>${next.title}</small></a></nav></div>`}

function renewalAsset(index){return `/assets/hs-renewals-${String(index).padStart(2,'0')}.png`}
function renewalFigure(index,alt){return `<figure class="renewal-figure"><img src="${renewalAsset(index)}" alt="${alt}" loading="lazy" decoding="async"></figure>`}
function renewalCallout(title,body){return `<div class="hs-final-label renewal-callout"><strong>${title}</strong><p>${body}</p></div>`}
function renewalCompare(before,after,label,instructions=false){return `<div class="hs-comparison-section renewal-comparison"><div class="hs-heading"><span class="eyebrow">BEFORE / AFTER</span>${instructions?`<p>Drag the divider, use the arrow keys, or scroll horizontally over the image to compare ${label}.</p>`:''}</div><div class="comparison-slider" style="--position:50%"><img class="comparison-base" src="${renewalAsset(after)}" alt="After: ${label}"><div class="comparison-reveal"><img src="${renewalAsset(before)}" alt="Before: ${label}"></div><span class="comparison-label comparison-label-before" aria-hidden="true">Before</span><span class="comparison-label comparison-label-after" aria-hidden="true">After</span><span class="comparison-divider" aria-hidden="true"><span>‹ ›</span></span><input class="comparison-range" type="range" min="0" max="100" value="50" aria-label="Compare before and after ${label}"></div><div class="comparison-links"><button type="button" class="comparison-button" data-comparison-image="${renewalAsset(before)}" data-comparison-name="Before">View “Before”</button><button type="button" class="comparison-button" data-comparison-image="${renewalAsset(after)}" data-comparison-name="After">View “After”</button></div></div>`}
function renewalsCasePage(p){const origin=caseOrigin(p);return `<main class="hs-case renewals-case">
<section class="hs-intro wrap"><a class="back-link back-all-work" href="${origin.href}">${arrowIcon('left')} ${origin.label}</a>${caseBreadcrumb(p)}<h1><em>Streamline client renewals</em> for the 2026 enrollment year</h1><p class="hs-lede">Simplify how health insurance agents manage and renew client coverage while navigating changing plans, eligibility, and enrollment requirements for 2026</p><div class="hs-facts"><div><small>ROLE</small><strong>Senior product designer</strong></div><div><small>TEAM</small><strong>Product manager + two engineers</strong></div><div><small>DURATION</small><strong>2 months</strong></div></div></section>
<div class="renewal-hero wrap">${renewalFigure(18,'Final renewal comparison with current and renewing plans, provider filters, and a clear action to start a 2026 renewal')}</div>
<section class="hs-section hs-tint"><div class="wrap"><div class="renewal-impact-heading"><div class="hs-heading"><span class="eyebrow">IMPACT</span><h2>More clients were enrolled</h2><p>As part of a broader company-wide initiative, this project contributed to a 30%+ increase in enrollments completed through HealthSherpa for the 2026 enrollment year, despite a challenging political and regulatory environment. Renewals made up 1/3 of total enrollment volume on our platform.</p></div><strong class="renewal-impact-number">+30%</strong></div><div class="hs-metrics renewal-metrics"><div><strong>4 million</strong><span>Visits to the renewal comparison page</span></div><div><strong>1.8 million</strong><span>Applications launched from the renewal page</span></div><div><strong>800,000</strong><span>Plans updated from the renewals page</span></div><div><strong>391,000</strong><span>Passive applications actively renewed for 2026</span></div></div>${renewalCompare(10,18,'the previous and redesigned renewal comparison experiences',true)}</div></section>
<section class="hs-section"><div class="wrap"><div class="hs-heading">${caseProgress(1,5,'THE PROBLEM')}<h2>Agents lacked a clear way to start the renewal process and understand what was changing</h2><p>The existing renewal process lacked clear, consistent actions, provided little context on how renewals worked or where to start, and offered limited visibility into upcoming plan changes and what agents could expect for their clients.</p></div>${renewalCallout('THE DESIGN CHALLENGE','Help clarify for agents how they can start a renewal process, understand upcoming plan changes, and communicate updates with their clients.')}</div></section>
<section class="hs-section hs-tint"><div class="wrap"><div class="hs-heading">${caseProgress(2,5,'DISCOVERY')}<h2>What’s wrong with the current renewal journey?</h2><p>I led a kickoff workshop to critique the existing renewal experience and align the team on agent behaviors, existing research, and common support pain points.</p></div>${renewalFigure(12,'Workshop journey map of agent actions and the existing HealthSherpa renewal experience')}<div class="hs-insights renewal-insights"><article><span>01</span><h3>Inconsistent triggers spread throughout the entire app</h3><p>It’s unclear to agents how to start a renewal, if they should quote versus start an application first, or if they need to search and claim a passive application from the Marketplace</p></article><article><span>02</span><h3>Missing context about policy related renewal processes</h3><p>Agents don’t understand when or why they would need to search &amp; claim a passive renewal application generated by the federal Marketplace</p></article><article><span>03</span><h3>Limited information around enrollment changes</h3><p>Agents lacked visibility into upcoming carrier plan changes, making it difficult to confidently guide clients through renewals</p></article></div></div></section>
<section class="hs-section"><div class="wrap"><div class="hs-heading">${caseProgress(3,5,'EXPLORATIONS')}<h2>The renewal experience should be coupled more tightly together</h2><p>I explored 3 improvements that positioned the renewal experience as a system: a consistent entry point, clearer movement between plan years, and a comparison experience that could help agents understand what was changing before they acted.</p></div>
${renewalCallout('IMPROVEMENT #1','Consolidated renewal CTA for all enrollments')}<div class="renewal-sequence"><span class="eyebrow">BEFORE</span>${renewalFigure(2,'Previous renewal triggers spread across the renewal task view, client details, and book of business')}<span class="eyebrow">AFTER</span>${renewalFigure(13,'Exploration consolidating renewal actions into the client application page')}</div>
${renewalCallout('IMPROVEMENT #2','Link application to a plan year switcher that sets context around search &amp; claiming a passive application')}${renewalCompare(9,15,'the previous and explored plan-year navigation')}
${renewalCallout('IMPROVEMENT #3','Replace renewal interstitial with upcoming renewal estimates for comparison')}${renewalCallout('TECHNICAL CONSTRAINTS','Engineers flagged that adding provider, hospital, and RX filters on the comparison page would increase scope more than they would be beneficial. I challenged that assumption and wanted to collect agent feedback on its value before making the decision to remove it from the experience.')}${renewalCompare(11,18,'the renewal interstitial and upcoming plan estimates')}
</div></section>
<section class="hs-section hs-tint"><div class="wrap"><div class="hs-heading">${caseProgress(4,5,'USABILITY TESTING ROUND 1')}<h2>Agents needed clearer direction to kickstart renewals and better tools to navigate client conversations</h2><p>I tested the improved renewal flow with 5 agents to evaluate if they could identify and understand how to renew their upcoming client book of business</p></div>
${renewalCallout('RESEARCH TAKEAWAY #1','Agents could generally find the renewal CTA but having to choose between a quote versus an application gave people pause in terms of what they would expect to see next and if either flow would allow them to complete the renewal in its totality')}${renewalCompare(14,5,'the explored renewal actions and the focused renewal entry point')}
${renewalCallout('RESEARCH TAKEAWAY #2','Agents found it helpful to switch between plan years but 2 agents found it a bit difficult to notice the action. They understood from the historical dropdown that if there was a missing application record, they would need to search for it on the federal Marketplace.')}${renewalCompare(8,3,'the previous application navigation and clarified plan-year states')}
${renewalCallout('RESEARCH TAKEAWAY #3','Agents found the comparison screen particularly helpful for seeing upcoming changes, but it was unclear how the toggles would change the page information below and whether they could start an application after enrolling in the plan itself.')}${renewalCompare(16,18,'the first comparison concept and the revised renewal estimate')}
${renewalCallout('RESEARCH TAKEAWAY #4','Getting accurate information before Open Enrollment was mission critical for agents and some agents wanted to use HealthSherpa as the platform to initiate those types of conversations.<br><br>“We need to get key information so we can fill in the gaps – income, family size, anything that affects their tax credit. I want to do things right the first time so I don’t look stupid to my clients”')}<div class="renewal-feature-pair"><span class="eyebrow">NEW FEATURE REQUEST — BEFORE / AFTER</span><div class="renewal-image-pair">${renewalFigure(7,'Previous bulk email modal with a renewal message preview')}${renewalFigure(17,'Redesigned bulk renewal email with an editable pre-enrollment check-in template')}</div></div>
</div></section>
<section class="hs-section"><div class="wrap"><div class="hs-heading">${caseProgress(5,5,'THE FINAL EXPERIENCE')}<h2>All roads lead to successful renewals</h2><p>The new renewal flow focused agents into a single CTA, provided context on when agents would need to search &amp; claim an application to kick start renewal, gave more visibility into plan changes, and allowed agents to initiate early conversations with clients.</p></div><div class="hs-final-annotated">
<div class="hs-final-row">${renewalCallout('PRE-ENROLLMENT EMAIL','A modernized in-product email experience became a foundational pattern for other email touch points adopted by other product teams')}${renewalFigure(4,'Final pre-enrollment email template and reusable template selector')}</div>
<div class="hs-final-row">${renewalCallout('RENEWAL COMPARISON','A redesigned interstitial gives agents the ability to get a quote for upcoming plan changes and crosswalk changes while testing for in network providers, hospitals, and prescriptions')}${renewalFigure(18,'Final renewal comparison showing current and renewing plan costs and network filters')}</div>
<div class="hs-final-row">${renewalCallout('SINGLE ENTRY POINTS','Renewals always start from the client page with a focused clear action regardless of the plan year. Agents would be guided to search and claim to start the renewal or would be taken to the renewal comparison page if it was the current plan year')}${renewalFigure(5,'Final renewal entry points for current and prior-year applications')}</div></div>
<div class="renewal-handoff"><h3>I worked closely with engineers to map out all of the renewal entry points and various states of each screen based on open enrollment timing</h3>${renewalFigure(6,'Engineering handoff mapping renewal screens, entry points, and search-and-claim states across open enrollment timing')}</div></div></section>
${caseNextWork(p)}</main>`}

function healthSherpaCasePage(p){const origin=caseOrigin(p);return `<main class="hs-case">
<section class="hs-intro wrap"><a class="back-link back-all-work" href="${origin.href}">${arrowIcon('left')} ${origin.label}</a>${caseBreadcrumb(p)}<h1>Redesigning a homepage<br>for health marketplace agents</h1><p class="hs-lede">Redesigning the starting point for health insurance agents to prioritize urgent follow-ups, identity clients that need servicing, and work with more current information</p><div class="hs-facts"><div><small>ROLE</small><strong>Senior product designer</strong></div><div><small>TEAM</small><strong>2 product managers + 3 engineers</strong></div><div><small>DURATION</small><strong>3 months</strong></div></div></section>
<figure class="hs-visual hs-hero-visual wrap">${healthSherpaShowcase()}</figure>
<section class="hs-section hs-results-intro"><div class="wrap"><div class="hs-heading"><span class="eyebrow">IMPACT</span><h2>A more useful daily overview</h2><p>Feature launch showed the new homepage was helpful for orienting agents around daily work</p></div><div class="hs-metrics"><div><strong>300%+</strong><span>Increase in the rate of traffic to an existing follow-ups page to complete client tasks</span></div><div><strong>93%+</strong><span>Opt-in rate during Beta period to keep the new homepage experience instead of reverting</span></div><div><strong>89%</strong><span>49 of 55 beta survey respondents rated usefulness for daily work a 4 or 5 out of 5</span></div><div><strong>80%+</strong><span>Agent base engaged with the homepage during the Special Enrollment Period</span></div></div><div class="hs-comparison-section"><div class="hs-heading"><span class="eyebrow">BEFORE / AFTER</span><p>Drag the divider, use the arrow keys, or scroll horizontally over the image to compare the previous and redesigned homepages.</p></div><div class="comparison-slider" style="--position:50%"><img class="comparison-base" src="/assets/healthsherpa-agent-home-final.png" alt="Redesigned agent homepage with search, priority follow-ups, tasks, and resources"><div class="comparison-reveal"><img src="/assets/healthsherpa-before.png" alt="Previous agent homepage with notifications, news, and an enrollment chart"></div><span class="comparison-label comparison-label-before" aria-hidden="true">Before</span><span class="comparison-label comparison-label-after" aria-hidden="true">After</span><span class="comparison-divider" aria-hidden="true"><span>‹ ›</span></span><input class="comparison-range" type="range" min="0" max="100" value="50" aria-label="Reveal before and after homepage designs"></div><div class="comparison-links"><button class="comparison-button" type="button" data-comparison-image="/assets/healthsherpa-before.png" data-comparison-name="Before">View “Before”</button><button class="comparison-button" type="button" data-comparison-image="/assets/healthsherpa-agent-home-final.png" data-comparison-name="After">View “After”</button></div></div></div></section>

<section class="hs-section hs-plain"><div class="wrap hs-split"><div class="hs-heading">${caseProgress(1,7,'THE PROBLEM')}<h2>The homepage was easily skipped because it didn't have helpful information</h2></div><div class="hs-prose"><p>Agents could choose to opt-out and land on their client list. The previous home page had an opt out rate of 55% and leadership questioned whether a new homepage would be helpful at all.</p><div class="hs-callout"><strong>The design challenge</strong><span>Help agents orient around their next important actions, focus on servicing their clients, and provide useful information to power their productivity</span></div></div></div></section>
<section class="hs-section hs-tint"><div class="wrap"><div class="hs-heading">${caseProgress(2,7,'DISCOVERY')}<h2>What do agents actually need?</h2><p>I led a series of activities and analyzed existing research and user behavior to pinpoint the content that users prioritize and want to be notified about</p></div><div class="hs-insights"><article><span>01</span><h3>Follow-ups first</h3><p>Agents start their day by reviewing outstanding client documents and payments (SVIs, DMIs, &amp; binders)</p></article><article><span>02</span><h3>Real time data</h3><p>Agents need real-time accurate data in order to trust our numbers and provided tasks</p></article><article><span>03</span><h3>Diverse task list</h3><p>Other important tasks mentioned were client outreach recommendations, Marketplace notices, status updates, and additional training</p></article></div><div class="hs-research-map" aria-label="Research inputs"><div><small>INTERVIEWS</small><strong>8 users</strong><span>Understand user goals, daily work, unmet needs, and evaluate the current home page</span></div><div><small>INTERNAL SURVEY</small><strong>9 support agents</strong><span>Understand agent pain points and common questions</span></div><div><small>TEAM WORKSHOP</small><strong>Growth + Engineers</strong><span>Identify information that help agents act and understand early constraints</span></div><div><small>ANNUAL SURVEY</small><strong>~2,000 responses</strong><span>Real-time updates and guided training were the top two asks from our annual user survey</span></div></div></div></section>
<section class="hs-section hs-plain"><div class="wrap"><div class="hs-heading">${caseProgress(3,7,'EXPLORATIONS')}<h2>How do users want to receive this information?</h2><p>I explored 3 approaches and ran 1-hour interview sessions with 9 agents to understand their workflows and evaluate the different concepts</p></div><div class="hs-concept-gallery"><figure class="hs-concept-lead"><figcaption><strong>Concept 1 – Modular Overview</strong> A task-oriented homepage that surfaces priority work through focused modules</figcaption><img src="/assets/healthsherpa-concept-modular.png" loading="lazy" alt="Modular homepage concept with priority tasks, outreach, and activity"></figure><figure><figcaption><strong>Concept 2 – An activity feed</strong> A chronological stream of updates organized by category</figcaption><img src="/assets/healthsherpa-concept-feed.png" loading="lazy" alt="Chronological activity feed concept"></figure><figure><figcaption><strong>Concept 3 – Search, follow-ups, and activity</strong> A direct route to clients, a dedicated follow-ups module, and everything else as updates</figcaption><img src="/assets/healthsherpa-concept-search.png" loading="lazy" alt="Homepage concept combining search, follow-ups, and activity"></figure></div><div class="hs-takeaways"><strong>RESEARCH TAKEAWAYS</strong><ol><li>Users liked the modular approach the most if it could be combined with the search functionality of concept 3</li><li>Agents hated concept 2 as a notifications / activity feed and the categories were easily missed</li><li>All 9 agents felt the new homepage was an improvement to the current homepage</li></ol></div></div></section>
<section class="hs-section hs-tint"><div class="wrap hs-split"><div class="hs-heading">${caseProgress(4,7,'SCOPE DISCUSSIONS')}<h2>Prioritizing the highest-impact modules</h2></div><div class="hs-prose"><p>Engineering reviews ruled out some of the breadth of the modular concept. Real-time counts and individual sections were costly to build. I prioritized the top pieces of information with my PM and growth stakeholders to focus on the top agent and business priorities.</p><div class="hs-decision-grid"><div><small>KEEP</small><strong>Follow-ups · Policy status · Outreach suggestions · Marketplace notices · Agent training</strong></div><div><small>DESCOPE</small><strong>Client activity updates · Recent leads · Carriers and licenses · Account updates</strong></div></div></div></div></section>
<section class="hs-section hs-plain"><div class="wrap"><div class="hs-heading">${caseProgress(5,7,'LAYOUT TESTS')}<h2>Content mattered more to users than layout but the business wanted to drive a focus towards training</h2><p>I tested different layouts with 4 agents to understand which layout helped them focus their attention best. I also incorporated feedback from leadership around highlighting agent resources.</p></div><div class="hs-layouts"><figure><img src="/assets/healthsherpa-layout-time.png" loading="lazy" alt="Time-based homepage layout with follow-ups organized by urgency"></figure><figure><img src="/assets/healthsherpa-layout-tasks.png" loading="lazy" alt="Homepage layout grouping tasks and illustrated resources"></figure><figure><img src="/assets/healthsherpa-layout-balanced.png" loading="lazy" alt="Balanced layout for follow-ups and resources"></figure></div><div class="hs-takeaways"><strong>RESEARCH TAKEAWAYS</strong><ol><li>Users liked the focus on search and follow-ups that needed their attention</li><li>Users liked seeing all of their remaining tasks grouped together</li><li>Agents didn’t care much for agent resources, but reacted more positively when it was paired with visuals</li><li>The business wanted to focus on training because data showed higher activation when users engage with training materials</li></ol></div></div></section>
<section class="hs-section hs-tint"><div class="wrap"><div class="hs-split"><div class="hs-heading">${caseProgress(6,7,'INCORPORATING TECHNICAL CHALLENGES')}<h2>Real-time data requires manual user syncs</h2></div><div class="hs-prose"><p>Marketplace data can become stale because regulations require agents to sync each client manually. To make the homepage useful with up-to-date data, I needed to encourage agents to sync their clients regularly somehow. I built an interactive prototype in Lovable and tested it with 5 agents to understand how they interpreted and interacted with batch sync entry points.</p></div></div><figure class="hs-visual hs-sync-figure"><img src="/assets/healthsherpa-sync-demo.gif" loading="lazy" alt="Animated homepage prototype showing agents hovering to sync applications and watching the sync progress"></figure><div class="hs-takeaways"><strong>RESEARCH TAKEAWAYS</strong><ol><li>Agents automatically went to hover to sync their applications even if they didn’t understand what was happening at first</li><li>All agents eventually understood the syncs were taking place and it changed their mental model of how the platform works</li><li>The progress bar was particularly important for helping agents understand what was happening</li></ol></div></div></section>
<section class="hs-section hs-plain"><div class="wrap"><div class="hs-heading">${caseProgress(7,7,'THE FINAL EXPERIENCE')}<h2>A more useful place to start</h2><p>The new homepage focused users on client search. SVI, DMI, and unpaid binders lead the top priorities followed by notices, outreach, application statuses. Visual training remains prominent.</p></div><figure class="hs-visual hs-final"><img src="/assets/healthsherpa-agent-home-final.png" loading="lazy" alt="Full final homepage for HealthSherpa agents with client search, priority follow-ups, application syncing, outstanding tasks, and agent resources"></figure><div class="hs-final-annotated">
<div class="hs-final-row"><div class="hs-final-label"><strong>CLIENT SEARCH</strong><p>Helps agent service clients that need attention immediately</p></div><button class="hs-final-crop hs-final-search" type="button" data-zoom-src="/assets/healthsherpa-agent-home-final.png" data-zoom-name="Client search" aria-label="Enlarge client search screenshot"><svg viewBox="170 52 1045 210" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false"><image href="/assets/healthsherpa-agent-home-final.png" width="1920" height="1380"/></svg></button></div>
<div class="hs-final-row"><div class="hs-final-label-stack"><div class="hs-final-label"><strong>PRIORITIZED FOLLOW-UPS</strong><p>Outstanding documents and payments give agents focused client priorities for the day</p></div><div class="hs-final-label"><strong>APPLICATION SYNCS</strong><p>A hover interaction highlights data accuracy and allows agents to get real-time data easily</p></div></div><button class="hs-final-crop hs-final-followups" type="button" data-zoom-src="/assets/healthsherpa-agent-home-final.png" data-zoom-name="Prioritized follow-ups and application syncs" aria-label="Enlarge follow-ups and syncs screenshot"><svg viewBox="165 240 890 400" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false"><image href="/assets/healthsherpa-agent-home-final.png" width="1920" height="1380"/></svg></button></div>
<div class="hs-final-row"><div class="hs-final-label"><strong>OTHER OUTSTANDING TASKS</strong><p>Agents who prioritize additional tasks on top of follow-ups have a single space to get an overview of their book of business</p></div><button class="hs-final-crop hs-final-tasks" type="button" data-zoom-src="/assets/healthsherpa-agent-home-final.png" data-zoom-name="Other outstanding tasks" aria-label="Enlarge outstanding tasks screenshot"><svg viewBox="985 238 910 1090" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false"><image href="/assets/healthsherpa-agent-home-final.png" width="1920" height="1380"/></svg></button></div>
<div class="hs-final-row"><div class="hs-final-label"><strong>AGENT RESOURCE HUB</strong><p>Self-serve help, resources, and training are personalized and readily available on the homepage when agents get stuck</p></div><button class="hs-final-crop hs-final-resources" type="button" data-zoom-src="/assets/healthsherpa-agent-home-final.png" data-zoom-name="Agent resource hub" aria-label="Enlarge agent resource hub screenshot"><svg viewBox="165 600 900 720" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false"><image href="/assets/healthsherpa-agent-home-final.png" width="1920" height="1380"/></svg></button></div>
</div></div></section>
${caseNextWork(p)}</main>`}

function ukgMobileCasePage(p){const origin=caseOrigin(p);return `<main class="hs-case ukg-mobile-case"><section class="hs-intro wrap"><a class="back-link back-all-work" href="${origin.href}">${arrowIcon('left')} ${origin.label}</a>${caseBreadcrumb(p)}<h1>Making <em>employee feedback actionable</em> on mobile</h1><p class="hs-lede">An end-to-end mobile experience for employees and managers to ask for feedback, learn from it, and keep developing</p><div class="hs-facts"><div><small>ROLE</small><strong>Senior product designer</strong></div><div><small>TEAM</small><strong>2 designers · 2 product owners<br>2 content writers · 10 engineers</strong></div><div><small>DURATION</small><strong>3 months</strong></div></div></section><div class="wrap ukg-hero"><figure class="ukg-figure"><img src="/assets/ukg-mobile-hero.svg?v=4" alt="Mobile feedback history, giving feedback, and receiving feedback" fetchpriority="high"></figure></div><section class="hs-section hs-tint"><div class="wrap"><div class="hs-heading"><span class="eyebrow">IMPACT</span><h2>Make feedback easier, more frequent, and more meaningful for the manual workforce</h2><p>I designed a 0-to-1 Beta experience mobile app for an employee workforce on-the-go</p></div><div class="hs-metrics ukg-metrics"><div><strong>1000+</strong><span>Active employees sharing feedback during Beta launch</span></div><div><strong>15+</strong><span>Enterprise customers who purchased the Beta product</span></div></div></div></section><section class="hs-section "><div class="wrap"><div class="hs-heading">${caseProgress(1,6,'THE PROBLEM')}<h2>The existing continuous feedback experience wasn’t accessible on the go</h2><p>The existing experience was difficult to navigate on mobile, creating friction for deskless employees who relied on their phones or tablet to give, receive, and manage continuous feedback as part of their company processes</p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-03.png" alt="Existing desktop continuous feedback request details" loading="lazy" decoding="async"></figure><div class="hs-callout"><strong>The design challenge</strong><span>Make feedback easier, more frequent, and more meaningful for a manual workforce</span></div></div></section><section class="hs-section hs-tint"><div class="wrap"><div class="hs-heading">${caseProgress(2,6,'DISCOVERY')}<h2>Audit the experience before adapting it</h2><p>I conducted a preliminary audit of the existing experience and what we had learned from customers. Three opportunities shaped the work: improve organization, emphasize key topics, and promote trending. A competitor review then identified patterns in feedback mental models and wayfinding, including progressive disclosure and grouping by topic.</p></div><div class="ukg-annotated"><div class="hs-final-label"><strong>Improve organization</strong><p>Tracking feedback over time can be difficult when information is in a flat historical list</p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-06.png" alt="Improve organization audit of the existing feedback experience" loading="lazy" decoding="async"></figure></div><div class="ukg-annotated"><div class="hs-final-label"><strong>Promote trending</strong><p>The results page can do more to help employee growth by showing trending reports & areas of opportunity for employees</p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-04.png" alt="Promote trending audit of the existing feedback experience" loading="lazy" decoding="async"></figure></div><div class="ukg-annotated"><div class="hs-final-label"><strong>Growth emphasis</strong><p>The subject of the feedback needed more emphasis around the key area of growth they are trying to improve over time</p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-05.png" alt="Growth emphasis audit of the existing feedback experience" loading="lazy" decoding="async"></figure></div><div class="hs-final-label"><strong>Competitive review</strong><p>Across other mobile feedback tools, progressive disclosure was a common pattern, allowing users to drill down by topic without overwhelming the initial experience.</p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-07.png" alt="Competitive review of mobile feedback mental models and wayfinding" loading="lazy" decoding="async"></figure></div></section><section class="hs-section "><div class="wrap"><div class="hs-heading">${caseProgress(3,6,'GUIDING PRINCIPLES')}<h2>Stakeholder workshops helped us prioritize 5 key requirements for the initial product</h2><p>I planned and facilitated a workshop across our product, engineering, and content teams to align the team on five requirements for the initial release</p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-08.png" alt="Cross-functional workshop boards prioritizing initial product requirements" loading="lazy" decoding="async"></figure><div class="hs-takeaways"><strong>Our guiding product principles</strong><ol><li>Empower the employee by focusing on bottom-up relationships</li><li>Offer coaching opportunities to both managers & employees</li><li>Focus on choice interactions and reduce the need to type</li><li>Make asking for feedback easier and improve the existing mental model</li><li>Make meaningful feedback easy to give</li></ol></div></div></section><section class="hs-section hs-tint"><div class="wrap"><div class="hs-heading">${caseProgress(4,6,'EXPLORATIONS')}<h2>Organize feedback around skills that people want to develop over time</h2><p>Through design critiques with other designers and stakeholders, I refined the flows. The first revisions grouped feedback by topic, explored a single-scroll request form, and introduced feedback continuity so people could connect feedback over time.</p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-09.png" alt="Early wireframes grouping feedback by topic, progressive disclosure, request flow, and historical feedback" loading="lazy" decoding="async"></figure><div class="ukg-subsection"><p>I worked with the content and branding team to create detailed onboarding flows to offer coaching & guidance opportunities for employees and managers</p><figure class="ukg-figure "><img src="/assets/ukg-mobile-11.png" alt="Onboarding explorations with coaching and guidance" loading="lazy" decoding="async"></figure></div><div class="ukg-subsection"><p>I introduced progressive disclosure for items that need my attention, items for review, and requesting new feedback. I also revised the navigation model to group feedback by topics instead of individual one-off requests to improve the desktop experience, which was cited as challenging when it comes to finding information</p><figure class="ukg-figure "><img src="/assets/ukg-mobile-10.png" alt="Topic-based navigation and progressive disclosure explorations" loading="lazy" decoding="async"></figure></div><div class="ukg-subsection"><p>I added additional confirmations, in-line coaching tips on key user flows, and reference materials to offer encouragement and empower employees</p><figure class="ukg-figure "><img src="/assets/ukg-mobile-12.png" alt="In-line feedback coaching, confirmations, and reference material explorations" loading="lazy" decoding="async"></figure></div></div></section><section class="hs-section "><div class="wrap"><div class="hs-heading">${caseProgress(5,6,'USABILITY TESTING')}<h2>Testing revealed problems around onboarding, discoverability, and scanning</h2><p>I planned and facilitated usability studies with 6 employees and 6 managers</p></div><div class="hs-takeaways"><strong>Key themes</strong><ol><li>Managers of on-the-floor employees find that feedback tends to be more reactionary and negative</li><li>Continuously collecting feedback about performance for both employees and managers is a major cultural shift and will require more hand-holding from the organization</li><li>Managers expressed wanting more frequent, formal, and actionable feedback from their own leaders as well</li></ol></div><div class="ukg-subsection"><div class="hs-final-label"><strong>Improvement #1</strong><p>Feedback being a continuous scroll was unclear and additional questions were missed. We changed the design to be a stepper flow with focused questions instead</p></div><p class="ukg-comparison-help">Compare the before and after screens. Select an image to zoom in and explore the details.</p><div class="ukg-before-after"><div><span class="eyebrow">Before</span><figure class="ukg-figure ukg-phone"><img src="/assets/ukg-mobile-19.png" alt="Before: long continuous-scroll feedback request form" loading="lazy" decoding="async"></figure></div><div><span class="eyebrow">After</span><figure class="ukg-figure "><img src="/assets/ukg-mobile-14.png" alt="After: focused stepper flow for requesting feedback" loading="lazy" decoding="async"></figure></div></div></div><div class="ukg-subsection"><div class="hs-final-label"><strong>Improvement #2</strong><p>In-app guidance was easily missed, but employees found it helpful when prompted about the content. I visually emphasized the guidance in the app as an improvement</p></div><div class="ukg-before-after"><div><span class="eyebrow">Before</span><figure class="ukg-figure ukg-phone"><img src="/assets/ukg-mobile-17.png" alt="Before: understated in-app feedback guidance" loading="lazy" decoding="async"></figure></div><div><span class="eyebrow">After</span><figure class="ukg-figure "><img src="/assets/ukg-mobile-15.png" alt="After: visually emphasized coaching in feedback screens" loading="lazy" decoding="async"></figure></div></div></div><div class="ukg-subsection"><div class="hs-final-label"><strong>Improvement #3</strong><p>Onboarding flow felt too long; people thought the “pledge” was the most important content to set the context</p></div><div class="ukg-before-after"><div><span class="eyebrow">Before</span><figure class="ukg-figure "><img src="/assets/ukg-mobile-13.png" alt="Before: three-screen onboarding flow" loading="lazy" decoding="async"></figure></div><div><span class="eyebrow">After</span><figure class="ukg-figure ukg-phone"><img src="/assets/ukg-mobile-16.png" alt="After: focused feedback pledge" loading="lazy" decoding="async"></figure></div></div></div><div class="ukg-subsection ukg-annotated"><div class="hs-final-label"><strong>Improvement #4</strong><p>People only wanted actionable items in “What needs my attention” section. I removed the empty requests that were awaiting feedback and focused it just on actions where the employee needs to give feedback.</p></div><div><span class="eyebrow">After</span><figure class="ukg-figure "><img src="/assets/ukg-mobile-18.png" alt="After: actionable feedback tasks and recent feedback" loading="lazy" decoding="async"></figure></div></div></div></section><section class="hs-section hs-tint"><div class="wrap"><div class="hs-heading">${caseProgress(6,6,'WHAT WAS SHIPPED')}<h2>A 0-to-1 mobile app to help make feedback more actionable and frequent for a workforce without access to desktops</h2></div><div class="ukg-shipped-grid"><div><div class="hs-final-label"><strong>Onboarding</strong><p></p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-21.png" alt="Shipped focused feedback pledge" loading="lazy" decoding="async"></figure></div><div><div class="hs-final-label"><strong>In-app feedback coaching</strong><p></p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-22.png" alt="Shipped coaching in feedback history and detail views" loading="lazy" decoding="async"></figure></div><div><div class="hs-final-label"><strong>What needs my attention</strong><p></p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-23.png" alt="Shipped actionable tasks and recent feedback" loading="lazy" decoding="async"></figure></div></div><div class="hs-final-label"><strong>Guided flow to craft a feedback request (new design system component)</strong><p></p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-20.png" alt="Shipped guided feedback request stepper and confirmation" loading="lazy" decoding="async"></figure><div class="ukg-shipped-pair"><div><div class="hs-final-label"><strong>Giving feedback</strong><p></p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-24.png" alt="Shipped inbox and giving feedback flow" loading="lazy" decoding="async"></figure></div><div><div class="hs-final-label"><strong>Receiving feedback</strong><p></p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-25.png" alt="Shipped feedback topics, history, and results" loading="lazy" decoding="async"></figure></div></div><div class="hs-final-label"><strong>Flow diagrams illustrating the new navigation model differences for mobile vs. web experience</strong><p></p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-26.png" alt="Navigation and feedback request flow diagrams" loading="lazy" decoding="async"></figure><div class="hs-final-label"><strong>Auditing and documentation of all the differences between mobile and web experiences for product refactoring</strong><p></p></div><figure class="ukg-figure "><img src="/assets/ukg-mobile-27.png" alt="Mobile and web differences audit with proposed changes, priorities, and estimates" loading="lazy" decoding="async"></figure></div></section>${caseNextWork(p)}</main>`}

function monetizationCasePage(p){const origin=caseOrigin(p);return `<main class="hs-case monetization-case"><section class="hs-intro wrap"><a class="back-link back-all-work" href="${origin.href}">${arrowIcon('left')} ${origin.label}</a>${caseBreadcrumb(p)}<h1>Pricing, paywalls, and personalized plans</h1><p class="hs-lede">I drove paid conversion and subscription growth at Calendly by optimizing product-led growth channels and streamlining the post-trial purchase experience.</p><div class="hs-facts"><div><small>ROLE</small><strong>Senior product designer (Growth)</strong></div><div><small>TEAM</small><strong>Product manager · Data scientist<br>8 engineers</strong></div><div><small>DURATION</small><strong>6 months of ongoing experimentation</strong></div></div></section><div class="mon-hero wrap"><img src="/assets/calendly-mon-hero.svg?v=3" alt="Calendly pricing comparison, value-led paywall, and itemized checkout" fetchpriority="high"></div><section class="hs-section hs-tint"><div class="wrap"><div class="hs-heading"><span class="eyebrow">IMPACT</span><h2>Higher paid conversion across the product</h2><p>3 product-led growth improvements led to increased monetization for the company</p></div><div class="hs-metrics mon-impact-metrics"><div><strong>+10%</strong><span>Increase in the rate of users converting to a paid plan</span></div><div><strong>+1,200</strong><span>Increase in average monthly subscribing users</span></div></div></div></section><section class="hs-section "><div class="wrap"><div class="hs-heading">${caseProgress(1,6,'THE PROBLEM')}<h2>Improving paid conversion is a top OKR metric</h2><p>Calendly’s freemium business model relies on product-led growth to convert free users into paying customers. As the growth designer, my goal was to identify and reduce friction across key conversion touchpoints, creating more opportunities for users to discover the value of upgrading.</p></div><div class="hs-callout"><strong>The design challenge</strong><span>Improve the rate of new users purchasing subscriptions in their first 30 days</span></div></div></section><section class="hs-section hs-tint"><div class="wrap"><div class="hs-heading">${caseProgress(2,6,'DISCOVERY')}<h2>Users lack confidence and experience decision fatigue when comparing plans</h2><p>Qualitative interviews revealed that users lacked confidence in selecting the right plan based on their free trial, which delayed conversion.</p></div><figure class="mon-figure"><img src="/assets/calendly-mon-17.png?v=3" alt="User journey from sign-up through trial and post-trial purchase, including goals and known problems" loading="lazy" decoding="async"></figure><div class="mon-subsection"><h3>The current experience</h3><p>Calendly’s upgrade moments were spread across 48 different paywalls, a complex in-app pricing page, and an empty billing page</p><figure class="mon-figure"><img style="--native-image-width:2048px" src="/assets/calendly-mon-03.png?v=3" alt="Earlier paywall, pricing selector, and empty billing page" loading="lazy" decoding="async"></figure></div><div class="mon-subsection"><h3>Stakeholder workshops generated 3 experiments</h3><p>I facilitated a workshop to evaluate friction in existing experiences, brainstorm potential improvements, and prioritize opportunities with the greatest potential impact on conversion.</p><figure class="mon-figure"><img style="--native-image-width:2048px" src="/assets/calendly-mon-09.png?v=3" alt="Paid conversion workshop prompts and prioritized ideas" loading="lazy" decoding="async"></figure><div class="mon-three"><div class="hs-final-label"><strong>Experiment 1</strong><p>Improve pricing page</p></div><div class="hs-final-label"><strong>Experiment 2</strong><p>Improve paywalls</p></div><div class="hs-final-label"><strong>Experiment 3</strong><p>Improve checkout</p></div></div></div></div></section><section class="hs-section "><div class="wrap"><div class="hs-heading">${caseProgress(3,6,'EXPERIMENT 1')}<h2>Build decision confidence with the pricing page</h2><p>If we simplify team vs. individual plan choices, improve content hierarchy, and make the pricing page easier to scan, users will be more likely to select a paid plan because they can better understand the value of Calendly’s paid features.</p></div><div class="mon-subsection"><h3>Pricing pages should simplify plan comparisons</h3><p>Successful SaaS pricing pages commonly used concise plan summaries and unified comparisons of individual and team plans.</p><figure class="mon-figure"><img style="--native-image-width:2048px" src="/assets/calendly-mon-12.png?v=3" alt="SaaS pricing examples with concise plan summaries and unified individual and team comparisons" loading="lazy" decoding="async"></figure></div><div class="mon-subsection"><span class="eyebrow">BEFORE</span><figure class="mon-figure"><img style="--native-image-width:2048px" src="/assets/calendly-mon-13.png?v=3" alt="Before: separate pricing choices for individuals and teams" loading="lazy" decoding="async"></figure></div><div class="mon-subsection"><h3>User interviews & incremental A/B tests</h3><p>Successful SaaS pricing pages commonly used concise plan summaries and unified comparisons of individual and team plans.</p><div class="mon-annotated"><div class="hs-final-label"><strong>A/B test 1</strong><p>Removing teams toggle<br>49 days running<br>36,000 visitors<br>+3% in paid conversion (not conclusive)</p></div><figure class="mon-figure"><img src="/assets/calendly-mon-14.png?v=3" alt="First pricing experiment bringing individual and team plans together" loading="lazy" decoding="async"></figure></div><div class="mon-annotated"><div class="hs-final-label"><strong>Usability testing</strong><p>Updated content<br>Users didn’t want to click into each tab; they wanted to scroll on the full page</p></div><figure class="mon-figure"><img style="--native-image-width:1499px" src="/assets/calendly-mon-11.png?v=3" alt="Updated pricing content with consolidated plans and categorized feature comparison" loading="lazy" decoding="async"></figure></div></div><div class="mon-subsection"><span class="eyebrow">AFTER</span><figure class="mon-figure"><img src="/assets/calendly-mon-02.png?v=3" alt="After: concise pricing cards with billing choices and a full feature comparison" loading="lazy" decoding="async"></figure></div><div class="mon-outcome"><div><h3>Experiment 1 outcomes</h3><p>A/B experiment 30K+ users, 30 days, 99% confidence</p></div><div class="hs-metrics"><div><small class="eyebrow">PAID CONVERSION</small><strong>+4%</strong></div></div></div></div></section><section class="hs-section hs-tint"><div class="wrap"><div class="hs-heading">${caseProgress(4,6,'EXPERIMENT 2')}<h2>Standardize paywalls around feature value</h2><p>Calendly had 48 paywalled features with inconsistent messaging and upgrade experiences. By standardizing these touchpoints and clearly communicating feature value, we could reduce unexpected paywalls, help users recognize paid features, and encourage upgrades.</p></div><div class="mon-subsection"><span class="eyebrow">BEFORE</span><figure class="mon-figure"><img style="--native-image-width:2048px" src="/assets/calendly-mon-10.png?v=3" alt="Before: inconsistent upgrade prompts for calendar connections, workflows, branding, and event types" loading="lazy" decoding="async"></figure></div><div class="mon-subsection"><span class="eyebrow">AFTER</span><figure class="mon-figure"><img style="--native-image-width:2048px" src="/assets/calendly-mon-16.png?v=3" alt="After: consistent Standard and Teams paywalls with feature-value messaging and clear upgrade choices" loading="lazy" decoding="async"></figure></div><div class="mon-outcome"><div><h3>Experiment 2 outcomes</h3><p>A/B experiment 100K+ users, 14 days, 99% confidence</p></div><div class="hs-metrics"><div><small class="eyebrow">PAID CONVERSION</small><strong>+3%</strong></div></div></div></div></section><section class="hs-section "><div class="wrap"><div class="hs-heading">${caseProgress(5,6,'EXPERIMENT 3')}<h2>A checkout page without distractions</h2><p>If we focus checkout on a full page and clearly highlight savings and itemized costs, users will be more likely to complete their purchase because they feel confident in the pricing.</p></div><div class="mon-comparison hs-comparison-section"><div class="hs-heading"><span class="eyebrow">BEFORE / AFTER</span><p>Drag the divider, use the arrow keys, or scroll horizontally over the image to compare the previous and redesigned checkout.</p></div><div class="comparison-slider" style="--position:50%"><img class="comparison-base" src="/assets/calendly-mon-04.png?v=3" alt="After: full-page checkout"><div class="comparison-reveal"><img src="/assets/calendly-mon-06.png?v=3" alt="Before: checkout modal over the billing page"></div><span class="comparison-label comparison-label-before" aria-hidden="true">Before</span><span class="comparison-label comparison-label-after" aria-hidden="true">After</span><span class="comparison-divider" aria-hidden="true"><span>‹ ›</span></span><input class="comparison-range" type="range" min="0" max="100" value="50" aria-label="Compare before and after checkout"></div><div class="comparison-links"><button type="button" class="comparison-button" data-comparison-image="/assets/calendly-mon-06.png?v=3" data-comparison-name="Before">View “Before”</button><button type="button" class="comparison-button" data-comparison-image="/assets/calendly-mon-04.png?v=3" data-comparison-name="After">View “After”</button></div></div><div class="mon-outcome"><div><h3>Experiment 3 outcomes</h3><p>A/B experiment 100K+ users, 14 days, 99% confidence</p></div><div class="hs-metrics"><div><small class="eyebrow">PAID CONVERSION</small><strong>+2.6%</strong></div></div></div></div></section><section class="hs-section hs-tint"><div class="wrap"><div class="hs-heading">${caseProgress(6,6,'SHIPPED & SHARED')}<h2>Three experiments increased paid conversion by an estimated 1,200 monthly subscriptions</h2><p>I put together a source of truth for all pricing and feature-related content for the entire growth and product team to use for consistency.</p></div><figure class="mon-figure"><img style="--native-image-width:2048px" src="/assets/calendly-mon-15.png?v=3" alt="Shared source of truth for feature descriptions, pricing, and plan availability" loading="lazy" decoding="async"></figure><div class="hs-final-label"><strong>48 new paywalls leading to pricing comparisons and checkout</strong><p></p></div><figure class="mon-figure"><img src="/assets/calendly-mon-18.png?v=3" alt="Reusable paywall patterns and content guidance for Standard and Teams" loading="lazy" decoding="async"></figure><figure class="mon-figure"><div class="mon-pricing-preview"><img src="/assets/calendly-mon-01.png?v=5" alt="Shipped billing page with simplified plan summaries and the complete feature comparison" loading="lazy" decoding="async"></div></figure><figure class="mon-figure"><img src="/assets/calendly-mon-04.png?v=3" alt="Shipped full-page checkout with an itemized order summary" loading="lazy" decoding="async"></figure></div></section>${caseNextWork(p)}</main>`}

function calFigure(file,alt,caption,extra=''){return `<figure class="cal-figure ${extra}"><img src="/assets/calendly-${file}.png" loading="lazy" alt="${alt}"><figcaption>${caption}</figcaption></figure>`}
function metsFigure(file,alt,caption='',extra=''){return `<figure class="mets-figure ${extra}"><img src="/assets/calendly-mets-${file}.png" loading="lazy" alt="${alt}">${caption?`<figcaption>${caption}</figcaption>`:''}</figure>`}
function metsMetric(number,label,eyebrow=""){return `<div class="mets-metric">${eyebrow?`<small>${eyebrow}</small>`:""}<strong>${number}</strong><span>${label}</span></div>`}
function calendlyCasePage(p){const origin=caseOrigin(p);return `<main class="cal-case mets-case">
<section class="cal-intro wrap"><a class="back-link back-all-work" href="${origin.href}">${arrowIcon('left')} ${origin.label}</a>${caseBreadcrumb(p)}<h1>Driving adoption of<br><em>admin scheduling templates</em></h1><p class="cal-lede">Improve overall product retention by guiding scheduling admins to discover, create, and use managed event types across their teams</p><div class="cal-facts"><div><small>ROLE</small><strong>Senior product designer (Growth)</strong></div><div><small>TEAM</small><strong>Product manager · Data scientist · 5 engineers</strong></div><div><small>DURATION</small><strong>3 months</strong></div></div></section>
<div class="cal-hero-art wrap">${metsFigure('hero','Calendly managed event creation menu, landing page, and new editor together','','mets-hero')}</div>
<section class="cal-band mets-impact"><div class="wrap cal-band-grid"><div><span class="eyebrow">IMPACT</span><h2>More meetings were scheduled</h2><p>I designed three experiments that increased admin adoption of Managed Event Types for scheduling 5+ meetings across their team</p></div><strong class="cal-big-number">+60<span>%</span></strong></div></section>
<section class="cal-section"><div class="wrap"><div class="cal-heading">${caseProgress(1,6,'THE PROBLEM')}<h2>Admin managed event types were useful once adopted, but hard to discover</h2><p>Calendly’s Managed Event Types let admins create reusable scheduling templates for teams. They were part of a set of features tied to retention, but many admins were unaware of them or couldn’t find them</p></div><div class="mets-metrics three mets-problem-metrics">${metsMetric('15%','Of all teams had used the feature before','LOW ADOPTION RATE')}${metsMetric('72%','Of teams that used the feature booked 5+ meetings with it','BUT HIGH RETENTION')}${metsMetric('68%','Of teams that used the feature were satisfied with it','AND HIGH VALUE')}</div><div class="mets-challenge"><strong>The design challenge</strong><span>Make managed events easy to find, understand, and set up for admins</span></div></div></section>
<section class="cal-section cal-tint"><div class="wrap"><div class="cal-heading">${caseProgress(2,6,'DISCOVERY')}<h2>Managed events had both a visibility problem—and a setup problem, but the need for it was there</h2><p>Across 200+ survey responses, 5+ interviews, and 10 live sessions, three issues kept admins from using managed events</p></div><div class="mets-discovery"><article class="mets-discovery-row"><div class="mets-insight-stack"><div class="mets-insight"><span>01</span><h3>Hard to find</h3><p>Managed Event Types were buried at the bottom of a separate admin navigation</p></div><div class="mets-insight"><span>02</span><h3>Lack of education</h3><p>The value of the feature was unclear in the original landing state</p></div></div>${metsFigure('old-landing','Earlier Calendly Managed Event Types empty state with the admin navigation and limited explanation')}</article><article class="mets-discovery-row"><div class="mets-insight"><span>03</span><h3>Critical setup steps missed</h3><p>Assignment to team members was easy to overlook in the existing admin editor</p></div>${metsFigure('before','Earlier full-page managed event editor with assignment in a separate step')}</article></div></div></section>
<section class="cal-section"><div class="wrap"><div class="cal-heading">${caseProgress(3,6,'EXPERIMENT 1')}<h2>Make it easier to find</h2><p>Adding Managed Event Types to the top-level creation menu could make them easier to discover. The business also wanted other paid scheduling features to be more visible, so I explored the control and two alternatives before refining the final grouping and language</p></div>${metsFigure('global-create','Global creation menu comparison with control, two alternatives, and final variant','','mets-wide')}<div class="mets-results-heading"><strong>A/B experiment</strong><span>100K+ users · 14 days · 99% confidence</span></div><div class="mets-metrics four">${metsMetric('+52%','Admin managed events created')}${metsMetric('+28%','One-on-one events created')}${metsMetric('+58%','Group events created')}${metsMetric('+60%','Round-robin events created')}</div></div></section>
<section class="cal-section cal-tint"><div class="wrap"><div class="cal-heading">${caseProgress(4,6,'EXPERIMENT 2')}<h2>Introduce the feature in context and delay paywalls</h2><p>I designed a clearer empty state, a dedicated tab, and in-context entry points so admins could understand managed events as they worked. We also explored letting them create before encountering a paywall, so they could experience the value first</p></div><div class="mets-pair-block"><h3>New empty states and in-context creation</h3><div class="mets-image-pair">${metsFigure('landing','Redesigned Managed Event Types landing page with a clearer introduction')}${metsFigure('contextual','Contextual prompt to create a managed event while setting up scheduling')}</div></div><div class="mets-pair-block"><h3>Convert an existing event into a managed event type</h3><div class="mets-image-pair">${metsFigure('convert-card','Conversion entry point from an existing event card')}${metsFigure('convert-editor','Conversion entry point from the event editor')}</div><p class="mets-note">Conversion was descoped because it was too costly to include in the A/B test</p></div><div class="mets-results-heading"><strong>A/B experiment</strong><span>700K+ users · 20 days · 99% confidence</span></div><div class="mets-metrics three">${metsMetric('+41%','Managed events page visits')}${metsMetric('+55%','Managed events created')}${metsMetric('+61%','Managed event meetings booked')}</div></div></section>
<section class="cal-section"><div class="wrap"><div class="cal-heading">${caseProgress(5,6,'EXPERIMENT 3')}<h2>Modernize the admin editor to be more familiar</h2><p>The legacy admin editor felt different from Calendly’s newer creation patterns. I adapted the side-panel approach to make frequent actions easier to reach and clarify the order of setup</p></div>${metsFigure('editor-reference','Newer Calendly event editor patterns used as a reference for managed events','A familiar editor pattern created a foundation for the admin experience','mets-wide')}<div class="mets-design-rationale"><div><h3>Designing for how admins work</h3><p>I separated frequently edited event details from “set and forget” settings. Team assignment had been disconnected from the main flow, so the final direction brought it forward</p></div>${metsFigure('editor-reasoning','Design analysis of frequent settings, persistent settings, and assignment with an early editor variant')}</div><div class="mets-testing"><strong>USER TESTING RESULTS <span>(10 PARTICIPANTS)</span></strong><ol><li>All users preferred the new admin setup</li><li>Frequent actions were easy to find</li><li>Team assignment was still missed when placed last</li><li>Participants wanted more booking options at the first level</li></ol></div><div class="mets-comparison"><h3>Before and after</h3><p>Drag the divider, use the arrow keys, or scroll horizontally over the image to compare the editor experiences</p><div class="comparison-slider" style="--position:50%"><img class="comparison-base" src="/assets/calendly-mets-after.png" alt="Revised managed events landing and side-panel editor"><div class="comparison-reveal"><img src="/assets/calendly-mets-before.png" alt="Previous full-page managed event editor"></div><span class="comparison-label comparison-label-before" aria-hidden="true">Before</span><span class="comparison-label comparison-label-after" aria-hidden="true">After</span><span class="comparison-divider" aria-hidden="true"><span>‹ ›</span></span><input class="comparison-range" type="range" min="0" max="100" value="50" aria-label="Reveal before and after managed event editor designs"></div><div class="comparison-links"><button class="comparison-button" type="button" data-comparison-image="/assets/calendly-mets-before.png" data-comparison-name="Before">View “Before”</button><button class="comparison-button" type="button" data-comparison-image="/assets/calendly-mets-after.png" data-comparison-name="After">View “After”</button></div></div><div class="mets-results-heading"><strong>A/B experiment</strong><span>500K+ users · 20 days · 99% confidence</span></div><div class="mets-metrics two">${metsMetric('+13%','Managed events created')}${metsMetric('+24%','Managed event meetings booked')}</div></div></section>
<section class="cal-section cal-tint mets-shipped"><div class="wrap"><div class="cal-heading">${caseProgress(6,6,'WHAT WAS SHIPPED')}<h2>A clearer path from discovery to setup</h2><p>Improvements to discoverability, education, and setup helped increase adoption of managed events by 60%</p></div><div class="mets-shipped-row"><div class="mets-shipped-label"><strong>A more useful starting point</strong><span>Help admins understand managed events and find the next step</span></div>${metsFigure('landing','Shipped Managed Event Types landing page')}</div><div class="mets-shipped-row"><div class="mets-shipped-label"><strong>Create in context</strong><span>Introduce team scheduling where the need appears</span></div>${metsFigure('contextual','Contextual managed event creation prompt')}</div><div class="mets-shipped-duo"><div class="mets-shipped-row"><div class="mets-shipped-label"><strong>More awareness</strong><span>Put managed events in a familiar creation menu</span></div><button class="mets-component-crop mets-menu-crop" type="button" data-zoom-src="/assets/calendly-global-create-exploration.png" data-zoom-name="Final creation menu" aria-label="Enlarge final creation menu screenshot"><svg viewBox="2820 485 790 990" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false"><image href="/assets/calendly-global-create-exploration.png" width="4512" height="2160"/></svg></button></div><div class="mets-shipped-row"><div class="mets-shipped-label"><strong>Familiar editing</strong><span>Bring setup into a recognizable editor</span></div><button class="mets-component-crop mets-editor-crop" type="button" data-zoom-src="/assets/calendly-final-editor.png" data-zoom-name="Final editor" aria-label="Enlarge final managed event editor screenshot"><svg viewBox="2260 350 900 1770" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false"><image href="/assets/calendly-final-editor.png" width="3240" height="2256"/></svg></button></div></div></div></section>
${caseNextWork(p)}</main>`}

function activationFigure(file,alt,caption,extra=''){return `<figure class="activation-figure ${extra}"><img src="/assets/calendly-activation-${file}.webp" loading="lazy" alt="${alt}"><figcaption>${caption}</figcaption></figure>`}
function nuAsset(index){return `/assets/calendly-nu-${String(index).padStart(2,'0')}.png`}
function nuFigure(index,alt,caption=''){return `<figure class="nu-figure"><img src="${nuAsset(index)}" alt="${alt}" loading="lazy" decoding="async">${caption?`<figcaption>${caption}</figcaption>`:''}</figure>`}
function nuCompare(before,after,label){return nuSlider(before,after,label)}
function nuSlider(before,after,label){return `<div class="nu-comparison hs-comparison-section"><div class="hs-heading"><span class="eyebrow">BEFORE / AFTER</span><p>Drag the divider, use the arrow keys, or scroll horizontally over the image to compare the previous and redesigned ${label.toLowerCase()}.</p></div><div class="comparison-slider" style="--position:50%"><img class="comparison-base" src="${nuAsset(after)}" alt="After: ${label}"><div class="comparison-reveal"><img src="${nuAsset(before)}" alt="Before: ${label}"></div><span class="comparison-label comparison-label-before" aria-hidden="true">Before</span><span class="comparison-label comparison-label-after" aria-hidden="true">After</span><span class="comparison-divider" aria-hidden="true"><span>‹ ›</span></span><input class="comparison-range" type="range" min="0" max="100" value="50" aria-label="Compare before and after ${label}"></div><div class="comparison-links"><button type="button" class="comparison-button" data-comparison-image="${nuAsset(before)}" data-comparison-name="Before">View “Before”</button><button type="button" class="comparison-button" data-comparison-image="${nuAsset(after)}" data-comparison-name="After">View “After”</button></div></div>`}
function nuOutcomes(title,detail,metrics){return `<div class="nu-outcomes"><h3>${title}</h3><p>${detail}</p><div class="mets-metrics ${metrics.length===4?'four':metrics.length===3?'three':metrics.length===2?'two':'one'}">${metrics.map(([number,label])=>`<div class="mets-metric nu-outcome-metric"><h4>${label}</h4><strong>${number}</strong></div>`).join('')}</div></div>`}
function activationCasePage(p){const origin=caseOrigin(p);return `<main class="cal-case mets-case activation-case activation-revised">
<section class="cal-intro wrap"><a class="back-link back-all-work" href="${origin.href}">${arrowIcon('left')} ${origin.label}</a>${caseBreadcrumb(p)}<h1>Improving activation <em>of new Calendly users</em></h1><p class="cal-lede">Calendly’s new-user activation rate had been declining over time. I focused on identifying opportunities to better communicate Calendly’s value, drive adoption of high-retention features, and help more users successfully reach activation.</p><div class="cal-facts"><div><small>ROLE</small><strong>Senior product designer (Growth)</strong></div><div><small>TEAM</small><strong>Product manager · Data scientist · 5 engineers</strong></div><div><small>DURATION</small><strong>3 months</strong></div></div></section>
<div class="cal-hero-art wrap"><figure class="nu-hero"><img src="${nuAsset(1)}" alt="Calendly event types page with the redesigned getting-started guide for scheduling setup" decoding="async"></figure></div>
<section class="cal-section cal-tint nu-impact"><div class="wrap"><div class="cal-heading"><span class="eyebrow">IMPACT</span><h2>More meetings, stronger engagement</h2><p>3 experiments helped new users book meetings faster and adopt sticky features</p></div><div class="mets-metrics three">${metsMetric('+66%','Increase in the rate of feature adoption')}${metsMetric('+5.2%','Increase in the rate of meetings booked by week 2')}${metsMetric('$2.5M','Predicted ARR increase from conversion of high-retention features')}</div></div></section>
<section class="cal-section"><div class="wrap"><div class="cal-heading">${caseProgress(1,6,'THE PROBLEM')}<h2>New user taking action</h2><p>New users struggled to connect Calendly to their workflow. Activation interviews, customer feedback, and home-screen drop-off data showed that onboarding felt disconnected from their day-to-day scheduling needs. With 40% dropping off during sign-up and only 55% taking action in the app, there was an opportunity to provide clearer guidance and help users get to value faster.</p></div><div class="mets-metrics two">${metsMetric('40%','“Onboarding needs more guidance”','SIGN-UP DROP OFF')}${metsMetric('55%','“Onboarding is not connected to how I work”','FIRST USER ACTION')}</div><div class="mets-challenge"><strong>The design challenge</strong><span>Help new users quickly understand how Calendly fits into their workflow and get to value faster</span></div></div></section>
<section class="cal-section cal-tint"><div class="wrap"><div class="cal-heading">${caseProgress(2,6,'DISCOVERY')}<h2>New users have trouble discovering and understanding core features</h2><p>Qualitative interviews and surveys revealed that users struggled to understand Calendly’s capabilities and how they could use its features to improve their scheduling workflows—contributing to lower activation.</p></div>${nuFigure(3,'Research findings on awareness and understanding barriers, with feature adoption and retention data')}<div class="nu-subsection"><h3>Team brainstorm</h3><p>I led a cross-functional brainstorm that resulted in three prioritized, feasible experiments designed to help new users set up faster and better understand Calendly’s core features.</p><div class="nu-gallery two">${nuFigure(5,'Recorded activation brainstorm walkthrough')}${nuFigure(4,'Cross-functional activation brainstorm on a Miro board')}</div>${nuFigure(6,'Growth roadmap with ranked experiments and prioritization notes')}<div class="nu-experiments"><article><span>EXPERIMENT 1</span><p>New user set up guide</p></article><article><span>EXPERIMENT 2</span><p>Dedicated admin set up guide</p></article><article><span>EXPERIMENT 3</span><p>New user feature landing states</p></article></div></div></div></section>
<section class="cal-section"><div class="wrap"><div class="cal-heading">${caseProgress(3,6,'EXPERIMENT 1')}<h2>Guide individuals towards effective set up</h2><p>If we add more context and redesign the in-app onboarding module, then new users will be more likely to book meetings by week 2, because they have a better understanding of how to be set up successfully.</p></div><div class="nu-subsection"><h3>New user guides are core to best-in-SaaS products</h3><p>The use of <strong>granular, actionable steps in a comprehensive space in the app</strong> was a common trend across successful SaaS products.</p>${nuFigure(7,'Examples of actionable getting-started guidance across SaaS products')}<div class="nu-gallery three">${nuFigure(2,'Early exploration: getting-started steps above the home page')}${nuFigure(11,'Early exploration: a checklist in a focused overlay')}${nuFigure(12,'Early exploration: a persistent basics checklist beside the event list')}</div></div><div class="nu-subsection"><h3>User testing with activated users helped us identify opportunities to make the getting-started steps more actionable and guide users toward key actions.</h3>${nuCompare(14,13,'Getting-started guide')}<div class="nu-gallery three nu-guide-gallery">${nuFigure(8,'Get to know Calendly: introductory video and help articles')}${nuFigure(10,'The perfect scheduling setup: actionable steps for creating and sharing an event')}${nuFigure(9,'Automate your meeting experience: follow-up and integration setup guidance')}</div></div>${nuOutcomes('Experiment 1 outcomes','A/B experiment with 100K+ users over 59 days at 99.9% confidence',[['+5.2%','Activation rate'],['22%','Checklist completion'],['+8%','Trial to conversion']])}</div></section>
<section class="cal-section cal-tint"><div class="wrap"><div class="cal-heading">${caseProgress(4,6,'EXPERIMENT 2')}<h2>Guide new admin users to set up their teams</h2><p>Leadership team felt strongly about running a similar experiment specifically for admin user groups to set up their teams for collaborative scheduling.</p></div><div class="nu-subsection"><h3>Generating admin tasks</h3><p>I put together a journey map of admin tasks and leveraged existing admin help articles to identify the specific tasks that should be highlighted in the getting started guide.</p>${nuFigure(15,'Admin journey map, customer experience guides, and the resulting admin checklist')}<div class="nu-gallery nu-admin-gallery">${nuFigure(20,'Calendly event types with individual and team getting-started guides')}${nuFigure(21,'Set your team up for success: admin setup guide')}</div></div>${nuOutcomes('Experiment 2 outcomes','A/B experiment with 100K+ new admin users over 59 days at 99% confidence',[['+11.2%','Org branding'],['+47.4%','Integrations'],['+109%','Org templates'],['+13.9%','Adding users']])}</div></section>
<section class="cal-section"><div class="wrap"><div class="cal-heading">${caseProgress(5,6,'EXPERIMENT 3')}<h2>Redesign feature empty states to be more actionable and value driven</h2><p><strong>If we apply consistent, actionable, and clear landing experiences across the product,</strong> then new users will be more likely to engage with Calendly’s high-value features because they have a better understanding of what the feature is, and what their next best action should be.</p></div><div class="nu-subsection"><h3>Creating patterns for Calendly’s top features</h3><p>For experiment purposes, our team chose to test with just Calendly Routing Forms and admin scheduling templates.</p>${nuSlider(17,16,'Routing forms')}${nuOutcomes('Routing form outcomes','A/B experiment with 100K+ users over 40 days at 99% confidence',[['+26%','Published forms']])}${nuSlider(18,19,'Admin scheduling templates')}${nuOutcomes('Admin scheduling template outcomes','A/B experiment with 100K+ users over 30 days at 99% confidence',[['+55.3%','Feature adoption'],['+61%','Meetings booked']])}</div></div></section>
<section class="cal-section cal-tint"><div class="wrap"><div class="cal-heading">${caseProgress(6,6,'SHIPPED & SHARED')}<h2>Turning experiments into reusable product patterns</h2></div><div class="nu-subsection"><h3>I made the experiment learnings and components reusable for the rest of the product and design team</h3><p>I audited the full inventory of Calendly’s top features, including various pre-trial, post-trial, and expired trial states. I created empty state templates for the rest of the design team to adopt into their specialized core product areas.</p>${nuFigure(22,'Full feature inventory and empty-state patterns across different trial states')}<div class="nu-pattern-callout"><strong>3 TYPES OF FEATURES</strong><span>I created design system components for simple features, complex features, and templated features</span></div><div class="nu-pattern-grid"><div>${nuFigure(28,'Design system template for a simple feature empty state')}${nuFigure(24,'Meetings empty state using the simple feature pattern')}</div><div>${nuFigure(30,'Design system template for a feature with page content')}${nuFigure(25,'Workflows empty state with starter templates')}</div><div>${nuFigure(29,'Design system template for a complex feature with a skeleton preview')}${nuFigure(26,'Analytics empty state using the complex feature pattern')}</div></div><div class="nu-pattern-callout"><strong>GET STARTED GUIDES</strong><span>I created design system components for the get started guides across the product</span></div>${nuFigure(23,'Reusable feature patterns connected to getting-started guides and help articles')}${nuFigure(27,'Workflows page with a reusable getting-started guide')}</div></div></section>
${caseNextWork(p)}</main>`}

function imageViewerMarkup(){return `<dialog class="image-viewer" id="comparison-viewer" aria-label="Image viewer"><div class="image-viewer-head"><strong id="viewer-title"></strong><div class="image-viewer-controls"><button type="button" id="viewer-out" aria-label="Zoom out">−</button><output id="viewer-level" aria-live="polite">100%</output><button type="button" id="viewer-in" aria-label="Zoom in">+</button><button type="button" id="viewer-reset">Reset</button><button type="button" id="viewer-close" aria-label="Close image viewer">×</button></div></div><div class="image-viewer-scroll"><img id="viewer-image" alt=""></div></dialog>`}
function chatMarkup(){return `<div class="chat-overlay" id="chat" aria-hidden="true"><div class="chat-panel" role="dialog" aria-label="Ask about Amber"><div class="chat-bar"><span class="chat-brand">${sparkleIcon()} <strong>Ask Amber</strong><small>Portfolio guide</small></span><button class="chat-close" id="close-chat" aria-label="Close chat">×</button></div><div class="chat-conversation" id="messages"><div class="chat-message assistant"><span class="chat-avatar">${sparkleIcon()}</span><p>Hi! Explore a few quick questions about my work, or ask your own. This preview uses answers based on this portfolio.</p></div></div><div class="chat-bottom"><div class="prompts"><button data-question="What is your process?">Process</button><button data-question="What are your skills?">Skills</button><button data-question="What projects have you worked on?">Projects</button><button data-question="Tell me about Amber">About Amber</button></div><form id="chat-form"><input id="chat-input" aria-label="Ask a question" placeholder="Ask me about Amber…" autocomplete="off"><button aria-label="Send message" type="submit">${upIcon()}</button></form><small>Portfolio preview · answers are limited to information shown here</small></div></div></div>`}
let path=(portfolioLocal ? decodeURIComponent(location.pathname).slice(decodeURIComponent(portfolioRoot.pathname).length).replace(/index\.html$/, '') : location.pathname).split('/').filter(Boolean),content;if(path[0]==='work'){let c=companies.find(x=>x.id===path[1]);if(c){let p=all.find(x=>x.company.id===c.id&&x.pi===Number(path[2])-1);if(path[2]&&!p)location.replace(portfolioURL(`/work/${c.id}/`));content=p?casePage(p):companyPage(c)}else{location.replace(portfolioURL('/#work'));content=home()}}else content=home();app.innerHTML=portfolioMarkup(header()+content+footer()+imageViewerMarkup()+resumeViewerMarkup());
// The top anchor is outside the sticky header; every route scrolls its own page.
