// Let text occupy any width released by the content-height-capped square portrait.
{const grid=document.querySelector('.about-grid'),body=document.querySelector('.about-body'),prose=document.querySelector('.about-prose'),portrait=document.getElementById('portrait-card');if(grid&&body&&prose&&portrait){let pending=false;const fit=()=>{pending=false;const tablet=window.matchMedia('(min-width:768px) and (max-width:1100px)').matches;const height=Math.max(1,Math.floor((tablet?prose:body).getBoundingClientRect().height)-1);portrait.style.setProperty('--portrait-content-height',`${height}px`);if(window.matchMedia('(min-width:768px)').matches){const gap=parseFloat(getComputedStyle(grid).columnGap)||0;const width=Math.floor(Math.min((grid.clientWidth-gap)*.425,height));if(Math.abs((parseFloat(grid.style.getPropertyValue('--portrait-column-width'))||0)-width)>1)grid.style.setProperty('--portrait-column-width',`${width}px`)}};const schedule=()=>{if(!pending){pending=true;requestAnimationFrame(fit)}};const observer=new ResizeObserver(schedule);observer.observe(grid);observer.observe(body);observer.observe(prose);window.addEventListener('resize',schedule);schedule();}}

document.querySelectorAll('.comparison-slider').forEach(slider=>{const range=slider.querySelector('.comparison-range');const update=()=>slider.style.setProperty('--position',`${range.value}%`);range.addEventListener('input',update);slider.addEventListener('wheel',event=>{const delta=event.shiftKey?event.deltaY:event.deltaX;if(Math.abs(delta)<3||(!event.shiftKey&&Math.abs(delta)<Math.abs(event.deltaY)*.6))return;event.preventDefault();range.value=Math.max(0,Math.min(100,Number(range.value)+delta/slider.clientWidth*100));update()},{passive:false})});
const viewer=document.getElementById('comparison-viewer');
if(viewer){const image=viewer.querySelector('#viewer-image'),title=viewer.querySelector('#viewer-title'),level=viewer.querySelector('#viewer-level'),scroll=viewer.querySelector('.image-viewer-scroll');let zoom=1,pan=null;
function setZoom(value){const next=Math.max(.7,Math.min(3,Math.round(value*10)/10));if(next===zoom)return;const centerX=scroll.scrollLeft+scroll.clientWidth/2,centerY=scroll.scrollTop+scroll.clientHeight/2,ratio=zoom>0?next/zoom:1;zoom=next;image.style.setProperty('--zoom',zoom);level.textContent=Math.round(zoom*100)+'%';viewer.querySelector('#viewer-out').disabled=zoom<=.7;viewer.querySelector('#viewer-in').disabled=zoom>=3;scroll.scrollLeft=centerX*ratio-scroll.clientWidth/2;scroll.scrollTop=centerY*ratio-scroll.clientHeight/2}
function openImage(src,name,alt){image.src=src;image.alt=alt||name;title.textContent=name;zoom=0;setZoom(1);viewer.showModal();scroll.scrollTop=0;scroll.scrollLeft=0}
document.querySelectorAll('[data-comparison-image]').forEach(button=>button.addEventListener('click',()=>openImage(button.dataset.comparisonImage,button.dataset.comparisonName,button.dataset.comparisonName+' screenshot')));
document.querySelectorAll('[data-zoom-src]').forEach(button=>button.addEventListener('click',()=>openImage(button.dataset.zoomSrc,button.dataset.zoomName,button.dataset.zoomName+' screenshot')));document.querySelectorAll('main.hs-case img,main.cal-case img').forEach(item=>{if(item.closest('.comparison-slider'))return;item.classList.add('zoomable-image');item.tabIndex=0;item.setAttribute('role','button');item.setAttribute('aria-label','Enlarge image: '+(item.alt||'case study image'));const open=()=>{const fig=item.closest('figure');const name=fig?.querySelector('figcaption strong')?.textContent||fig?.querySelector('figcaption')?.textContent?.trim()||item.alt||'Case study image';openImage(item.currentSrc||item.src,name,item.alt)};item.addEventListener('click',open);item.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}})});
viewer.querySelector('#viewer-out').addEventListener('click',()=>setZoom(zoom-.2));viewer.querySelector('#viewer-in').addEventListener('click',()=>setZoom(zoom+.2));viewer.querySelector('#viewer-reset').addEventListener('click',()=>{zoom=0;setZoom(1);scroll.scrollTop=0;scroll.scrollLeft=0});viewer.querySelector('#viewer-close').addEventListener('click',()=>viewer.close());viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close()});
scroll.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;pan={x:e.clientX,y:e.clientY,left:scroll.scrollLeft,top:scroll.scrollTop};scroll.setPointerCapture(e.pointerId);scroll.classList.add('panning');e.preventDefault()});scroll.addEventListener('pointermove',e=>{if(!pan)return;scroll.scrollLeft=pan.left-(e.clientX-pan.x);scroll.scrollTop=pan.top-(e.clientY-pan.y)});function stopPan(){pan=null;scroll.classList.remove('panning')}scroll.addEventListener('pointerup',stopPan);scroll.addEventListener('pointercancel',stopPan);
viewer.addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();setZoom(zoom+(e.deltaY<0?.1:-.1))},{passive:false});viewer.addEventListener('close',()=>{image.removeAttribute('src');stopPan()})}

