const portrait=document.getElementById('portrait-card');
if(portrait){
 const expressions=['blink','double-blink','slow-blink','quick-blink','late-blink'];
 const motifs=[['sparkle','✦'],['star','⭐'],['moon','🌙'],['planet','🪐'],['alien','👽'],['ufo','🛸'],['ice-cream','🍦'],['pig','🐷'],['heart','💜'],['fire','🔥'],['croissant','🥐'],['shrimp','🦐'],['moon-face','🌚'],['sun-face','🌞'],['flying-money','💸']];
 const inventory=motifs.flatMap(([motif,glyph])=>expressions.map(expression=>({motif,glyph,expression})));
 const particle=portrait.querySelector('.portrait-particle');
 const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');
 let last=-1,locked=false;
 function react(){if(locked||reduce.matches)return;locked=true;let next=Math.floor(Math.random()*(last<0?inventory.length:inventory.length-1));if(last>=0&&next>=last)next++;last=next;const reaction=inventory[next];portrait.classList.remove('portrait-reacting');portrait.dataset.expression=reaction.expression;portrait.dataset.motif=reaction.motif;particle.textContent=reaction.glyph;void portrait.offsetWidth;portrait.classList.add('portrait-reacting');setTimeout(()=>{portrait.classList.remove('portrait-reacting');locked=false},1000)}
 portrait.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch')react()});
 portrait.addEventListener('pointermove',e=>{if(e.pointerType!=='touch')react()});
 portrait.addEventListener('click',react);
}

const hero=document.querySelector('.hero');
if(hero){const grid=hero.querySelector('.hero-star-grid'),content=[...hero.children].filter(el=>el!==grid);let stars=[],cols=0,rows=0,stepX=0,stepY=0,lastOrigin=-1,lastRipple=0;
 const sparkleMarkup='<span class="hero-grid-star"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linejoin="round" aria-hidden="true"><path d="M12 1.5c0 6-4.5 10.5-10.5 10.5 6 0 10.5 4.5 10.5 10.5 0-6 4.5-10.5 10.5-10.5-6 0-10.5-4.5-10.5-10.5Z"/></svg></span>';
 function sizeGrid(){const rect=grid.getBoundingClientRect(),nextCols=Math.max(8,Math.round(rect.width/30)-1),nextRows=Math.max(8,Math.round(rect.height/30)-1);if(nextCols!==cols||nextRows!==rows){cols=nextCols;rows=nextRows;grid.style.gridTemplateColumns=`repeat(${cols},minmax(0,1fr))`;grid.style.gridTemplateRows=`repeat(${rows},minmax(0,1fr))`;grid.innerHTML=sparkleMarkup.repeat(cols*rows);stars=[...grid.children];lastOrigin=-1}stepX=rect.width/(cols+1);stepY=rect.height/(rows+1);grid.style.paddingInline=`${stepX/2}px`;grid.style.paddingBlock=`${stepY/2}px`;const blocks=content.map(el=>el.getBoundingClientRect());stars.forEach((star,i)=>{const x=rect.left+(i%cols+1)*stepX,y=rect.top+(Math.floor(i/cols)+1)*stepY;const distance=Math.min(...blocks.map(block=>Math.hypot(Math.max(block.left-x,0,x-block.right),Math.max(block.top-y,0,y-block.bottom)))),fade=Math.max(0,Math.min(1,(distance-8)/115)),strength=fade*fade*(3-2*fade);star.motionStrength=strength;star.style.setProperty('--rest-opacity',(.09+.11*strength).toFixed(3));star.style.setProperty('--peak-opacity',(.09+.76*strength).toFixed(3));star.style.setProperty('--ring-opacity',(.24*strength).toFixed(3));star.style.setProperty('--sparkle-scale',(1+.16*strength).toFixed(3));star.style.setProperty('--origin-scale',(1+.4*strength).toFixed(3))})}
 sizeGrid();addEventListener('resize',sizeGrid,{passive:true});document.fonts?.ready.then(sizeGrid);
 // Sparse night-sky twinkles run independently of the pointer ripple.
 const ambientMotion=matchMedia('(prefers-reduced-motion:reduce)'),activeTwinkles=new Map();let ambientTimer=0,heroVisible=false,lastTwinkled=null;
 function stopAmbient(){clearTimeout(ambientTimer);ambientTimer=0;activeTwinkles.forEach((timer,star)=>{clearTimeout(timer);star.classList.remove('ambient-twinkle')});activeTwinkles.clear()}
 function scheduleAmbient(){if(ambientTimer||!heroVisible||document.hidden||ambientMotion.matches)return;ambientTimer=setTimeout(twinkleAmbient,600+Math.random()*1000)}
 function twinkleAmbient(){ambientTimer=0;if(!heroVisible||document.hidden||ambientMotion.matches)return;const candidates=stars.filter(star=>star.motionStrength>.2&&!star.classList.contains('ripple')&&!activeTwinkles.has(star)&&star!==lastTwinkled);const count=Math.random()<.4?3:2;for(let i=0;i<count&&candidates.length;i++){const star=candidates.splice(Math.floor(Math.random()*candidates.length),1)[0],duration=1800+Math.random()*900;lastTwinkled=star;star.style.setProperty('--ambient-duration',`${duration}ms`);star.style.setProperty('--ambient-peak',(.224+.496*star.motionStrength).toFixed(3));star.style.setProperty('--ambient-ring-opacity',(.32*star.motionStrength).toFixed(3));star.classList.add('ambient-twinkle');activeTwinkles.set(star,setTimeout(()=>{star.classList.remove('ambient-twinkle');activeTwinkles.delete(star)},duration+50))}scheduleAmbient()}
 const ambientObserver=new IntersectionObserver(entries=>{heroVisible=entries[0].isIntersecting;if(heroVisible)scheduleAmbient();else stopAmbient()},{threshold:0});ambientObserver.observe(hero);
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAmbient();else scheduleAmbient()});ambientMotion.addEventListener('change',()=>{if(ambientMotion.matches)stopAmbient();else scheduleAmbient()});
 if(matchMedia('(pointer:fine) and (prefers-reduced-motion:no-preference)').matches){document.addEventListener('pointermove',e=>{const rect=grid.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom){lastOrigin=-1;return}const col=Math.max(0,Math.min(cols-1,Math.round((e.clientX-rect.left)/stepX)-1)),row=Math.max(0,Math.min(rows-1,Math.round((e.clientY-rect.top)/stepY)-1)),origin=row*cols+col,now=performance.now();if(origin===lastOrigin||now-lastRipple<105)return;lastOrigin=origin;if(stars[origin].motionStrength<.02)return;lastRipple=now;for(let r=Math.max(0,row-3);r<=Math.min(rows-1,row+3);r++)for(let c=Math.max(0,col-3);c<=Math.min(cols-1,col+3);c++){const star=stars[r*cols+c];if(star.motionStrength<.02)continue;const distance=Math.hypot((c-col)*stepX,(r-row)*stepY);if(distance>Math.max(stepX,stepY)*2.15)continue;const token=(star.rippleToken||0)+1;star.rippleToken=token;star.style.setProperty('--ripple-delay',`${Math.min(distance/850,.15)}s`);star.classList.remove('ripple','ripple-origin');void star.offsetWidth;star.classList.add('ripple');if(r*cols+c===origin)star.classList.add('ripple-origin');setTimeout(()=>{if(star.rippleToken===token)star.classList.remove('ripple','ripple-origin')},680)}},{passive:true})}
}

const carousel=document.getElementById('carousel');if(carousel){const stackedWork=()=>window.matchMedia('(max-width:800px)').matches;const cards=[...carousel.querySelectorAll('.project-card')],count=cards.length/3,thumb=document.getElementById('carousel-thumb'),track=thumb.parentElement;const segment=()=>cards[count].offsetLeft-cards[0].offsetLeft;const targetLeft=i=>cards[i].offsetLeft+cards[i].offsetWidth/2-carousel.clientWidth/2;let activeIndex=count,settleTimer,programmatic=false,dragging=false,moved=false,startX=0,startLeft=0,startIndex=count,draggedUntil=0;function nearest(){const center=carousel.scrollLeft+carousel.clientWidth/2;let best=0,distance=Infinity;cards.forEach((c,i)=>{const d=Math.abs(c.offsetLeft+c.offsetWidth/2-center);if(d<distance){distance=d;best=i}});return best}function update(){if(stackedWork())return;activeIndex=nearest();cards.forEach((c,i)=>{c.classList.toggle('is-active',i===activeIndex);c.setAttribute('aria-current',i===activeIndex?'true':'false')});const projectCount=count,position=((activeIndex%projectCount)+projectCount)%projectCount,step=segment()/projectCount,raw=(carousel.scrollLeft-targetLeft(projectCount))/step,phase=((raw%projectCount)+projectCount)%projectCount,visual=phase<=projectCount-1?phase:(projectCount-1)*(projectCount-phase);thumb.style.width=`${100/projectCount}%`;thumb.style.left=`${visual*100/projectCount}%`;track.setAttribute('aria-valuemin','1');track.setAttribute('aria-valuemax',projectCount);track.setAttribute('aria-valuenow',position+1);track.setAttribute('aria-valuetext',`Project ${position+1} of ${projectCount}`)}function rebase(){if(stackedWork())return;const i=nearest();if(i>=count&&i<count*2)return;carousel.classList.add('rebasing');carousel.scrollLeft+=i<count?segment():-segment();update();requestAnimationFrame(()=>requestAnimationFrame(()=>carousel.classList.remove('rebasing')))}function finishMove(){programmatic=false;rebase()}function settle(){if(dragging||programmatic)return;const i=nearest();if(Math.abs(carousel.scrollLeft-targetLeft(i))>2)go(i);else rebase()}function go(i,behavior='smooth'){if(stackedWork())return;i=Math.max(0,Math.min(cards.length-1,i));clearTimeout(settleTimer);programmatic=true;carousel.scrollTo({left:targetLeft(i),behavior});activeIndex=i;cards.forEach((c,n)=>c.classList.toggle('is-active',n===i));settleTimer=setTimeout(finishMove,850)}function advance(direction,from=nearest()){clearTimeout(settleTimer);programmatic=false;if(from<count||from>=count*2){rebase();from=nearest()}go(from+direction)}carousel.scrollLeft=targetLeft(count);update();carousel.addEventListener('scroll',()=>{update();if(!dragging&&!programmatic){clearTimeout(settleTimer);settleTimer=setTimeout(settle,480)}},{passive:true});window.addEventListener('resize',()=>go(count,'auto'));document.getElementById('prev').onclick=()=>advance(-1);document.getElementById('next').onclick=()=>advance(1);track.addEventListener('click',e=>{const ratio=Math.max(0,Math.min(1,(e.clientX-track.getBoundingClientRect().left)/track.clientWidth));go(count+Math.min(count-1,Math.floor(ratio*count)))});track.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();advance(e.key==='ArrowLeft'?-1:1)}});carousel.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse')return;dragging=true;moved=false;startX=e.clientX;startLeft=carousel.scrollLeft;startIndex=nearest();clearTimeout(settleTimer)});carousel.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-startX;if(Math.abs(dx)>5){if(!moved)carousel.setPointerCapture(e.pointerId);moved=true;carousel.classList.add('dragging');carousel.scrollLeft=startLeft-dx}});function endDrag(){if(moved)draggedUntil=performance.now()+350;dragging=false;carousel.classList.remove('dragging');clearTimeout(settleTimer);const delta=startLeft-carousel.scrollLeft;if(moved&&Math.abs(delta)>35)advance(delta>0?1:-1,startIndex);else settleTimer=setTimeout(settle,480)}carousel.addEventListener('pointerup',endDrag);carousel.addEventListener('pointercancel',endDrag);let wheelLockedUntil=0;carousel.addEventListener('wheel',e=>{if(stackedWork())return;const horizontal=e.shiftKey||Math.abs(e.deltaX)>Math.abs(e.deltaY)*.6;if(!horizontal)return;e.preventDefault();if(performance.now()<wheelLockedUntil)return;const delta=Math.abs(e.deltaX)>1?e.deltaX:e.deltaY;if(Math.abs(delta)<4)return;wheelLockedUntil=performance.now()+500;advance(delta>0?1:-1)},{passive:false});let touchStartX=0,touchStartIndex=count;carousel.addEventListener('touchstart',e=>{touchStartX=e.touches[0].clientX;touchStartIndex=nearest()},{passive:true});carousel.addEventListener('touchend',e=>{const dx=touchStartX-e.changedTouches[0].clientX;if(Math.abs(dx)>40){clearTimeout(settleTimer);setTimeout(()=>advance(dx>0?1:-1,touchStartIndex),60)}},{passive:true});carousel.addEventListener('click',e=>{if(performance.now()<draggedUntil){e.preventDefault();e.stopPropagation()}},true)}
